class Cat {
    String name;
    int fish;

    void eat(int n) {
        fish = fish + n;
    }
}

public class Main {
    public static void main(String[] args) {
        Cat c1 = new Cat();
        c1.name = "小橘";
        Cat c2 = new Cat();
        c2.name = "狸花";

        c1.eat(3);
        c2.eat(5);
        c1.eat(4);
        System.out.println(c1.name + " " + c1.fish);
        System.out.println(c2.name + " " + c2.fish);
    }
}

